"""Emit a fused boxed projection using the generated team's typed accessors."""

import json
import sys
from pathlib import Path
from openpilot.cereal import log

indices = {name: index for index, name, _ in json.loads(Path(sys.argv[1]).read_text())}
lines = [
    "#pragma once",
    "// Include after accessors.h; generated by experiments/bulk/generate_consumer.py.",
    """
inline PyObject* bulk_pack(std::initializer_list<PyObject*> values) {
  PyObject* tuple = PyTuple_New(values.size());
  bool failed = !tuple;
  for (auto* value: values) if (!value) failed = true;
  if (failed) { for (auto* value: values) Py_XDECREF(value); Py_XDECREF(tuple); return nullptr; }
  unsigned i = 0;
  for (auto* value: values) PyTuple_SET_ITEM(tuple, i++, value);
  return tuple;
}
inline PyObject* generated_projection(Handle* h) {
  try {
    const char* kind = which_value(0, h->reader);
""",
]


def getter(schema, field, handle):
    f = schema.fields[field].proto
    assert f.which() == "slot", "projection does not support group fields"
    if f.slot.type.which() in ("list", "struct", "data", "text"):
        assert not f.slot.hadExplicitDefault, "projection requires null pointer defaults"
    return f"get_{indices[schema.node.displayName]}_{list(schema.fields).index(field)}(&{handle})"


def child(schema, field, parent, name):
    f = schema.fields[field]
    assert f.proto.which() == "slot" and f.proto.slot.type.which() == "struct"
    assert not f.proto.slot.hadExplicitDefault, "projection requires null struct defaults"
    schema = f.schema
    lines.append(
        f"Handle {name}(h->owner,{parent}.reader.getPointerField({f.proto.slot.offset}).getStruct(nullptr),{indices[schema.node.displayName]});"
    )
    return schema


root = log.Event.schema
lines += [
    f"Owned valid({getter(root, 'valid', '(*h)')});",
    f"Owned timestamp({getter(root, 'logMonoTime', '(*h)')});",
    "Owned values(nullptr);",
]
for index, kind in enumerate(["carState", "carControl", "modelV2", "longitudinalPlan"]):
    lines.append(f'{"if" if index == 0 else "else if"} (std::strcmp(kind,"{kind}")==0) {{')
    schema = child(root, kind, "(*h)", "body")
    if kind == "carState":
        nested = child(schema, "wheelSpeeds", "body", "wheels")
        values = [
            getter(schema, "vEgo", "body"),
            getter(schema, "steeringAngleDeg", "body"),
            getter(nested, "fl", "wheels"),
            getter(schema, "gearShifter", "body"),
        ]
    elif kind == "carControl":
        nested = child(schema, "actuators", "body", "actuators")
        values = [
            getter(schema, "enabled", "body"),
            getter(nested, "accel", "actuators"),
            getter(nested, "torque", "actuators"),
        ]
    elif kind == "modelV2":
        pos = child(schema, "position", "body", "position")
        meta = child(schema, "meta", "body", "meta")
        field = schema.fields["leadsV3"]
        assert not field.proto.slot.hadExplicitDefault, "projection requires null list defaults"
        lead = field.schema.elementType
        lines += [
            f"auto leads = body.reader.getPointerField({field.proto.slot.offset}).getList(capnp::ElementSize::INLINE_COMPOSITE,nullptr);",
            "Owned xs(PyList_New(leads.size())); check(xs.p);",
            f"for (unsigned i=0;i<leads.size();++i) {{ Handle lead(h->owner,leads.getStructElement(i),{indices[lead.node.displayName]});",
            f"auto* x={getter(lead, 'x', 'lead')};check(x);PyList_SET_ITEM(xs.p,i,x);}}",
        ]
        values = [getter(pos, "x", "position"), "xs.release()", getter(meta, "laneChangeState", "meta")]
    else:
        values = [getter(schema, f, "body") for f in ["speeds", "accels", "shouldStop"]]
    lines += ["values.p = bulk_pack({" + ",".join(values) + "}); check(values.p);", "}"]
lines += [
    "else { values.p = Py_NewRef(Py_None); }",
    "return bulk_pack({interned(kind),bulk_pack({valid.release(),timestamp.release()}),values.release()});",
    "} catch (...) { return error(); }",
    "}",
    """
inline PyObject* projected(PyObject* data) {
  try {
    if (!PyBytes_Check(data) || PyBytes_GET_SIZE(data)%8) throw std::runtime_error("expected word-aligned bytes length");
    auto owner=std::make_shared<Owner>(data);
    auto ptr=capnp::_::PointerHelpers<capnp::AnyPointer>::getInternalReader(owner->reader->getRoot<capnp::AnyPointer>());
    Handle root(owner,ptr.getStruct(nullptr),0);
    return generated_projection(&root);
  } catch (...) { return error(); }
}
""",
]
Path(sys.argv[2]).write_text("\n".join(lines))
